const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function researchImagesPanel(value){if(!value)return '';return `<section class="panel" id="research-image-settings-panel"><div class="panel-heading"><div><h2>科研绘图生成配置</h2><p>基础与专业绘图共用图像生成服务；模型及密钥仅管理员可见。</p></div><span class="service-status ${value.ready?'':'off'}">${value.ready?'配置已启用':'保存并启用后开放'}</span></div><form id="research-image-settings-form" class="settings-body" autocomplete="off"><p class="settings-note">每次生成一张图片；输入描述经文本审核，生成图片受图像服务安全策略约束。文件只保存到私有 OSS。图片用量按张记录，不混入文本 Token。</p><div class="payment-field-grid"><div class="payment-field"><label for="research-image-model">图像模型</label><select id="research-image-model" name="model">${(value.models||[]).map(model=>`<option value="${esc(model)}" ${value.model===model?'selected':''}>${esc(model)}</option>`).join('')}</select></div><div class="payment-field"><label for="research-image-workspaceId">百炼业务空间 ID</label><input id="research-image-workspaceId" name="workspaceId" value="${esc(value.workspaceId)}" maxlength="68" placeholder="ws-…"></div><div class="payment-field"><label for="research-image-apiKey">图像服务密钥（留空保留）</label><input id="research-image-apiKey" name="apiKey" type="password" autocomplete="new-password" maxlength="4096" placeholder="${value.credentialConfigured?'已配置，留空保留':'可复用当前百炼业务空间的密钥'}"></div><div class="payment-field"><label for="research-image-timeoutMs">等待上限（毫秒）</label><input id="research-image-timeoutMs" name="timeoutMs" type="number" min="10000" max="180000" step="1000" value="${Number(value.timeoutMs)||120000}"></div></div><label class="toggle-row" for="research-image-enabled"><span><b>启用 AI 科研绘图</b><p>关闭后暂停新生成；历史图片保留。后台可在“商品与计费”单独设置科研绘图价格。</p></span><input id="research-image-enabled" name="enabled" type="checkbox" ${value.enabled?'checked':''}></label><p class="settings-note">当前接入阿里云官方中国内地共享入口，密钥与业务空间需有对应模型调用权限。保存不触发付费生图；业务验收可在科研工具确认报价后执行。</p>${value.encryptionReady?'':'<p class="page-notice">服务器配置加密密钥未就绪。</p>'}${value.configurationError?`<p class="page-notice">${esc(value.configurationError)}</p>`:''}<p class="form-error" data-image-config-error role="alert" hidden></p><p class="settings-note" data-image-dirty hidden>有绘图配置尚未保存</p><div class="settings-actions"><button class="button primary" type="submit" ${value.encryptionReady?'':'disabled'}>保存科研绘图配置</button></div></form></section>`;}
export function researchImagesPayload(form,value){return {version:value.version,enabled:form.elements.enabled.checked,baseURL:'https://dashscope.aliyuncs.com',workspaceId:form.elements.workspaceId.value.trim(),model:form.elements.model.value,apiKey:form.elements.apiKey.value.trim(),timeoutMs:Number(form.elements.timeoutMs.value)};}
